 \"title\"}, {\"bbox\": [{\"coord\": [640, 430, 864, 478], \"page_id\": 7}], \"content\": \"May 1970\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [-4, 886, 1575, 1929], \"page_id\": 7}], \"content\": null, \"description\": null, \"id\": 2, \"type\": \"figure\"}, {\"bbox\": [{\"coord\": [116, 1979, 1313, 2087], \"page_id\": 7}], \"content\": \"UNITED STATES TREASURY DEPARTMENT OFFICE OF THE SECRETARY\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [634, 1020, 1082, 1049], \"page_id\": 8}], \"content\": \"The Treasury Bulletin is for sale by the\", \"description\": null, \"id\": 0, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [696, 1044, 1022, 1070], \"page_id\": 8}], \"content\": \"Superintendent of Documents.\", \"description\": null, \"id\": 1, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [539, 1068, 1178, 1092], \"page_id\": 8}], \"content\": \"U.S. Government Printing Office, Washington, D.C. 20402\", \"description\": null, \"id\": 2, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [576, 1087, 1151, 1113], \"page_id\": 8}], \"content\": \"Subscription per year $13.50 domestic, $17.00 foreign.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [724, 1109, 992, 1135], \"page_id\": 8}], \"content\": \"Single copy price varies.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 17, 215, 70], \"page_id\": 9}], \"content\": \"May 1970\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1494, 46, 1516, 82], \"page_id\": 9}], \"content\": \"\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [656, 291, 871, 322], \"page_id\": 9}], \"content\": \"CONTENTS\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [100, 440, 1380, 1811], \"page_id\": 9}], \"content\": \"<table><tr><td>Treasury financing operations.</td><td>III</td></tr><tr><td>Federal fiscal operations.</td><td>1</td></tr><tr><td>Federal obligations.</td><td>13</td></tr><tr><td>Account of the Treasurer of the United States.</td><td>17</td></tr><tr><td>Monetary statistics.</td><td>20</td></tr><tr><td>Federal debt</td><td>21</td></tr><tr><td>Public debt operations.</td><td>29</td></tr><tr><td>United States savings bonds.</td><td>64</td></tr><tr><td>United States savings notes.</td><td>69</td></tr><tr><td>Ownership of Federal securities.</td><td>70</td></tr><tr><td>Treasury survey of ownership</td><td>72</td></tr><tr><td>Market quotations on Treasury securities.</td><td>78</td></tr><tr><td>Average yields of long-term bonds.</td><td>81</td></tr><tr><td>International financial statistics.</td><td>83</td></tr><tr><td>Capital movements.</td><td>88</td></tr><tr><td>Financial operations of Government agencies and funds</td><td>125</td></tr><tr><td>Cumulative table of contents.</td><td>165</td></tr></table>\", \"description\": null, \"id\": 3, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [97, 1897, 1031, 1926], \"page_id\": 9}], \"content\": \"Note: Details of figures may not add to totals because of rounding.\", \"description\": null, \"id\": 4, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [16, 34, 61, 79], \"page_id\": 10}], \"content\": \"II\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1250, 5, 1562, 53], \"page_id\": 10}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [549, 288, 1054, 324], \"page_id\": 10}], \"content\": \"Treasury Financing Operations\", \"description\": null, \"id\": 2, \"type\": \"title\"}, {\"bbox\": [{\"coord\": [25, 478, 196, 511], \"page_id\": 10}], \"content\": \"May Refunding\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [25, 518, 783, 857], \"page_id\": 10}], \"content\": \"On April 29 the Treasury announced an exchange offering of an additional amount of the 7-3/4% Treasury Notes of Series A-1973, dated October 1, 1969, due May 15, 1973, at 99.40 (to yield about 7.98%); and an additional amount of the 8% Treasury Notes of Series A-1977, dated February 15, 1970, due February 15, 1977, at par and accrued interest from February 15 to May 15, 1970 ($19.66851 per $1,000) to holders of 5-5/8%\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [829, 446, 1587, 530], \"page_id\": 10}], \"content\": \"Treasury Notes of Series B-1970, due May 15, 1970, and 6-3/8%\\nTreasury Notes of Series C-1970, due May 15, 1970.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [836, 549, 1586, 732], \"page_id\": 10}], \"content\": \"Subscriptions totaled $4,682 million for the 7-3/4% notes and $3,310 million for the 8% notes, of which $2,421 million and $2,125 million, respectively, were received from Federal Reserve banks and Government accounts.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 751, 1593, 833], \"page_id\": 10}], \"content\": \"The following table contains preliminary figures relating to amounts exchanged by the public.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [631, 869, 984, 900], \"page_id\": 10}], \"content\": \"(Dollar amounts in millions)\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [39, 893, 1593, 1260], \"page_id\": 10}], \"content\": \"<table><tr><th colspan=\\\"2\\\">ELIGIBLE FOR EXCHANGE</th><th colspan=\\\"3\\\">NOTES TO BE ISSUED</th><th colspan=\\\"2\\\">UNEXCHANGED</th></tr><tr><th>Notes</th><th>Amount</th><th>7-3/4% A-1973</th><th>8% A-1977</th><th>Total</th><th>Amount</th><th>Percent</th></tr><tr><td>5-5/8% B-1970</td><td>$2,331</td><td>$1,074</td><td>$600</td><td>$1,674</td><td>$657</td><td>28.2</td></tr><tr><td>6-3/8% C-1970</td><td>2,551</td><td>1,186</td><td>585</td><td>1,771</td><td>780</td><td>30.6</td></tr><tr><td>Total</td><td>$4,882</td><td>$2,260</td><td>$1,185</td><td>$3,445</td><td>$1,437</td><td>29.4</td></tr></table>\", \"description\": null, \"id\": 9, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [41, 1332, 792, 1416], \"page_id\": 10}], \"content\": \"The subscription books were open from May 4 through May 6. Cash subscriptions were not accepted.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [45, 1435, 804, 1665], \"page_id\": 10}], \"content\": \"Coupons dated May 15, 1970, were to be detached from the maturing notes. The may 15, 1970, interest due on registered notes was paid by issue of interest checks in regular course to holders of record on April 15, 1970, the date the transfer books closed.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [46, 1684, 806, 2064], \"page_id\": 10}], \"content\": \"Interest on the 7-3/4% notes will be payable semi-annually on November 15, 1970, and thereafter on May 15 and November 15 in each year until maturity. Interest on the 8% notes will be payable on a semiannual basis on August 15, 1970, and thereafter on February 15 and August 15 in each year until maturity. The notes are not subject to call for redemption prior to maturity. Bearer notes, with interest coupons attached, and notes registered as to principal\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [847, 1313, 1591, 1416], \"page_id\": 10}], \"content\": \"pal and interest were authorized to be issued in denomination of $1,000, $5,000, $10,000, $100,000, and $1,000,000.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [851, 1423, 1017, 1452], \"page_id\": 10}], \"content\": \"Cash Offering\", \"description\": null, \"id\": 14, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [853, 1464, 1589, 2054], \"page_id\": 10}], \"content\": \"On April 29 the Treasury also announced an offering for cash of $3.5 billion, or thereabouts, to the public of 7-3/4 percent Treasury Notes of Series G-1971, dated May 15, 1970, due November 15, 1971, at 99.95, to yield about 7.79 percent. An additional amount was to be allotted to Government accounts and Federal Reserve Banks. The subscription books were open only on Tuesday, May 5. Subscriptions from the public totaled $3,737 million, including $2,350 million from commercial banks for their own accounts and $1,387 million from all other subscribers, and were allotted in full. Government accounts and Federal Reserve banks were allotted $7,005 million of the notes.\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [1453, 29, 1504, 62], \"page_id\": 11}], \"content\": \"III\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [410, 284, 1091, 322], \"page_id\": 11}], \"content\": \"Treasury Financing Operations - (Continued)\", \"description\": null, \"id\": 1, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [0, 10, 183, 52], \"page_id\": 11}], \"content\": \"May 1970\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [0, 453, 737, 772], \"page_id\": 11}], \"content\": \"Interest is payable on the new notes semiannually on November 15, 1970, and May 15 and November 15, 1971. The notes are not subject to call for redemption prior to maturity. Bearer notes, with interest coupons attached, and notes registered as to principal and interest were authorized to be issued in denominations of $1,000, $5,000, $10,000, $100,000, and $1,000,000.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 801, 741, 1123], \"page_id\": 11}], \"content\": \"Subscriptions were received subject to allotment and were payable in cash or in Treasury notes maturing May 15, 1970, which were accepted at par, in payment or exchange, in whole or in part. Payment was required to be made or completed on or before May 15, 1970. Payment by credit in Treasury tax and loan accounts was permitted for 50 percent of the amount of notes allotted.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 1151, 739, 1473], \"page_id\": 11}], \"content\": \"Coupons dated May 15, 1970, on the maturing notes in bearer form submitted in payment for the new notes, were to be detached by holders and cashed when due. In the case of registered notes submitted in payment, the final interest due on May 15, 1970, was paid by issuance of interest checks in regular course to holders of record on April 15, 1970, the date the transfer books closed.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 1502, 742, 1924], \"page_id\": 11}], \"content\": \"Commercial banks could submit subscriptions for account of their customers provided the names of the customers were set forth in such subscriptions. Others than commercial banks were not permitted to enter subscriptions except for their own account. Commercial banks' subscriptions for their own account, were restricted in each case to an amount not exceeding 50 percent of the combined capital (not including capital notes or debentures), surplus, and undivided profits of the subscribing bank.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [11, 1948, 742, 2024], \"page_id\": 11}], \"content\": \"Subscriptions were received without deposit from banking institutions for their own account, Federally-insured savings\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [788, 460, 1514, 1023], \"page_id\": 11}], \"content\": \"and loan associations, States, political subdivisions or instrumentalities thereof, public pension and retirement and other public funds, international organizations in which the United States holds membership, foreign central banks and foreign States, and dealers who make primarymarkets in Government securities and report daily to the Federal Reserve Bank of New York their positions with respect to Government securities and borrowings thereon. All other subscriptions were required to be accompanied by payment of 10 percent (in cash or in the maturing notes, which were accepted at par) of the amount of notes applied for, not subject to withdrawal until after allotment.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [788, 1051, 1520, 1273], \"page_id\": 11}], \"content\": \"All subscribers were required to agree not to purchase or to sell, or to make any agreements with respect to the purchase or sale or other disposition of the notes subscribed for at a specific rate or price, until after midnight May 5, 1970.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [790, 1302, 1518, 1521], \"page_id\": 11}], \"content\": \"Commercial banks in submitting subscriptions were required to certify that they had no beneficial interest in any of the subscriptions they entered for the account of their customers, and that their customers had no beneficial interest in the banks' subscriptions for their own account.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [788, 1600, 1105, 1623], \"page_id\": 11}], \"content\": \"9-Month and One-year Bills\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [788, 1647, 1514, 2014], \"page_id\": 11}], \"content\": \"On April 16 tenders were invited for $500 million, or thereabouts, of 276-day Treasury bills, representing an additional amount of bills dated January 31, 1970, maturing January 31, 1971, and for $1.2 billion, or thereabouts, of 365-day Treasury bills to be dated April 30, 1970, to mature April 30, 1971, both series to be issued April 30. These issues were to refund $1,501 million of bills maturing April 30. Tenders were opened on April 23.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [45, 19, 98, 65], \"page_id\": 12}], \"content\": \"IV\", \"description\": null, \"id\": 0, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [1275, 19, 1580, 70], \"page_id\": 12}], \"content\": \"Treasury Bulletin\", \"description\": null, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [458, 290, 1182, 324], \"page_id\": 12}], \"content\": \"Treasury Financing Operations - (Continued)\", \"description\": null, \"id\": 2, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [39, 461, 794, 645], \"page_id\": 12}], \"content\": \"Tenders received for the 276-day bills totaled $1,001 million, of which $500 million was accepted, including $16 million of noncompetitive tenders. The average bank discount rate was 6.843 percent.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [43, 667, 808, 852], \"page_id\": 12}], \"content\": \"Tenders received for the 365-day bills totaled $1,725 million, of which $1,200 million was accepted, including $55 million of noncompetitive tenders. The average bank discount rate was 6.814 percent.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 893, 362, 924], \"page_id\": 12}], \"content\": \"13-Week and 26-Week Bills\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 941, 803, 1176], \"page_id\": 12}], \"content\": \"Issues of regular weekly Treasury bills in April totaled $15.5 billion, replacing $15.0 billion of maturing bills. There were five 91-day issues of $1.8 billion and five 182-day issues of $1.3 billion. Average rates for the new issues are shown in the following table.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [52, 1193, 797, 1706], \"page_id\": 12}], \"content\": \"<table><tr><th colspan=\\\"3\\\">13-week<br/>(Additional amount of bills of original maturity of 26 weeks)</th><th colspan=\\\"2\\\">26-week</th></tr><tr><th colspan=\\\"2\\\">Date of --</th><th>Approximate equivalent annual average rate 1/</th><th>Date of issue</th><th>Approximate equivalent annual average rate 1/</th></tr><tr><th>Additional issue</th><th>Original issue</th><th></th><th></th><th></th></tr><tr><td>1970<br/>Apr. 2<br/>9<br/>16<br/>23<br/>30</td><td>1970<br/>Jan. 2<br/>8<br/>15<br/>22<br/>29</td><td>6.329<br/>6.408<br/>6.310<br/>6.476<br/>6.876</td><td>1970<br/>Apr. 2<br/>9<br/>16<br/>23<br/>30</td><td>6.392<br/>6.455<br/>6.247<br/>6.494<br/>7.253</td></tr></table>\", \"description\": null, \"id\": 7, \"type\": \"table\"}, {\"bbox\": [{\"coord\": [59, 1699, 364, 1723], \"page_id\": 12}], \"content\": \"1/ Bank discount basis.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 1752, 351, 1780], \"page_id\": 12}], \"content\": \"Treasury Bills - General\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 1802, 772, 1936], \"page_id\": 12}], \"content\": \"Treasury bills are sold on a bid basis. The face amount is payable without interest at maturity. They are issued in bearer form only, and in denominations of $1,000, $5,000, $10,000, $50,000, $100,000, $500,000, and $1,000,000 (maturity\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [844, 454, 1584, 571], \"page_id\": 12}], \"content\": \"rity value) 1/. Tenders are received at Federal Reserve banks and branches. Each tender must be for a multiple of $10,000.\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [844, 588, 1582, 883], \"page_id\": 12}], \"content\": \"Banking institutions generally may submit tenders for account of customers. Tenders may be made without deposit by incorporated banks and trust companies and by responsible and recognized dealers in investment securities. Tenders from others must be accompanied by payment of 2 percent of the face amount of bills applied for, unless the tenders are accompanied by an express guaranty of payment by an incorporated bank or trust company.\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [845, 905, 1589, 1041], \"page_id\": 12}], \"content\": \"Noncompetitive tenders (without stated price), usually for $200,000 or less from any one bidder, are accepted in full at the average price of accepted competitive bids for an issue.\", \"description\": null, \"id\": 13, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [845, 1068, 1584, 1281], \"page_id\": 12}], \"content\": \"Payment for accepted tenders must be made or completed on the date of issue, in cash or other immediately available funds or in a like face amount of Treasury bills maturing on that date. Payment for 13-week, 26-week, 9-month, and one-year bills may not be made by credit in Treasury tax and loan accounts.\", \"description\": null, \"id\": 14, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [844, 1315, 1377, 1341], \"page_id\": 12}], \"content\": \"Foreign Series and Foreign Currency Series\", \"description\": null, \"id\": 15, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [844, 1361, 1587, 1593], \"page_id\": 12}], \"content\": \"Foreign series securities issued in April totaled $90 million, consisting of four certificates of indebtedness and two notes. Redemptions for the month totaled $1,154 million At the end of April foreign series securities outstanding totaled $2,620 million. (Details are shown on page 60.)\", \"description\": null, \"id\": 16, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [844, 1615, 1584, 1944], \"page_id\": 12}], \"content\": \"Foreign currency series securities issued in April consisted of one note denominated in Swiss francs equivalent to $52 million. Redemptions for the month totaled an equivalent of $107 million. At the end of April foreign currency series securities outstanding totaled an equivalent of $1,366 million and were denominated in German marks and Swiss francs. (Details are shown on page 63.)\", \"description\": null, \"id\": 17, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [57, 2052, 1436, 2083], \"page_id\": 12}], \"content\": \"Note: Details of Treasury market financing operations are shown elsewhere in tables on public debt operations.\", \"description\": null, \"id\": 18, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [55, 2083, 1573, 2131], \"page_id\": 12}], \"content\": \"1/ Effective with the Treasury bills issued on March 5, 1970, the $1,000 and $5,000 denominations are no longer authorized on original issue.\", \"description\": null, \"id\": 19, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [0, 10, 178, 64], \"page_id\": 13}], \"content\": \"May 1970\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1460, 55, 1476, 79], \"page_id\": 13}], \"content\": \"1\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [531, 88, 969, 117], \"page_id\": 13}], \"content\": \"FEDERAL FISCAL OPERATIONS\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [477, 145, 1010, 181], \"page_id\": 13}], \"content\": \"Table FFO-1. - Summary of Fiscal Operations\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [654, 210, 886, 229], \"page_id\": 13}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [0, 229, 1499, 1054], \"page_id\": 13}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">Fiscal year or month</th><th colspan=\\\"3\\\">The expenditure account</th><th colspan=\\\"4\\\">Loan account 1/</th><th colspan=\\\"5\\\">Means of financing - net transactions</th></tr><tr><th>Net receipts 2/</th><th>Net expenditures 3/</th><th>Surplus or deficit (-) (1)-(2) (3)</th><th>Loan disbursements (4)</th><th>Loan repayments (5)</th><th>Net lending 3/ (4)+(5) (6)</th><th>Outlays 2/ (2)-(6) (7)</th><th>Budget surplus or deficit (-) (3)+(6) (8)</th><th>Public debt securities (9)</th><th>Agency securi