 \"page_header\"}, {\"bbox\": [{\"coord\": [1481, 81, 1514, 110], \"page_id\": 95}], \"content\": \"83\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [473, 105, 1068, 141], \"page_id\": 95}], \"content\": \"INTERNATIONAL FINANCIAL STATISTICS\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [72, 254, 769, 400], \"page_id\": 95}], \"content\": \"The tables in this section are designed to provide data on United States reserve assets and liabilities and other statistics related to the United States balance of payments and international financial position. A number of changes were introduced in the May 1967 Bulletin to increase the usefulness of this section.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [67, 419, 769, 546], \"page_id\": 95}], \"content\": \"Table IFS-1 shows the reserve assets of the United States, including its gold stock, special drawing rights held in the Special Drawing Account in the International Monetary Fund, holdings of convertible foreign currencies, and reserve position in the International Monetary Fund.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [76, 563, 769, 685], \"page_id\": 95}], \"content\": \"Table IFS-2 brings together the various statistical components of the liabilities which enter into the United States balance of payments calculated on the liquidity basis. The inclusion of the United States reserve position in the International Monetary Fund in Table IFS-1 requires that the\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [818, 256, 1493, 331], \"page_id\": 95}], \"content\": \"\\\"holdings of dollars\\\" of the Fund be excluded from the data on liabilities to foreigners, in order to avoid double counting.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 357, 1495, 429], \"page_id\": 95}], \"content\": \"Table IFS-3 presents an area breakdown of United States liquid liabilities to official institutions of foreign countries.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [820, 453, 1493, 522], \"page_id\": 95}], \"content\": \"Table IFS-4 shows United States Treasury nonmarketable bonds and notes issued to official institutions of foreign countries.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [821, 544, 1495, 599], \"page_id\": 95}], \"content\": \"Table IFS-5 sets forth the factors which affect the United States position in the International Monetary Fund.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [821, 613, 1497, 690], \"page_id\": 95}], \"content\": \"Table IFS-6 presents United States net monetary gold transactions with foreign countries and international and regional organizations.\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [584, 1066, 1001, 1093], \"page_id\": 95}], \"content\": \"Table IFS-1. - U.S. Reserve Assets\", \"description\": null, \"id\": 11, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [672, 1129, 904, 1153], \"page_id\": 95}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 12, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [47, 1153, 1523, 1855], \"page_id\": 95}], \"content\": \"<table><tr><th>End of calendar year or month</th><th>Total reserve assets</th><th colspan=\\\"2\\\">Gold stock 1/</th><th>Special drawing rights 3/</th><th>Convertible foreign currencies 4/</th><th>Reserve position in International Monetary Fund 2/</th></tr><tr><th></th><th></th><th>Total 2/</th><th>Treasury</th><th></th><th></th><th></th></tr><tr><td>1957</td><td>24,832</td><td>22,857</td><td>22,781</td><td>-</td><td>-</td><td>1,975</td></tr><tr><td>1958</td><td>22,540</td><td>20,582</td><td>20,534</td><td>-</td><td>-</td><td>1,958</td></tr><tr><td>1959</td><td>21,504</td><td>19,507</td>