, \"id\": 1, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [385, 92, 1223, 119], \"page_id\": 28}], \"content\": \"ACCOUNT OF THE TREASURER OF THE UNITED STATES\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [357, 167, 1281, 201], \"page_id\": 28}], \"content\": \"Source and Availability of the Balance in the Treasurer's Account\", \"description\": null, \"id\": 3, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [45, 291, 767, 509], \"page_id\": 28}], \"content\": \"The working cash of the Treasury is held mainly in Treasurer's accounts with Federal Reserve banks and branches. As the balances in these accounts become depleted, they are restored by calling in (transferring) funds from the tax and loan accounts with thousands of commercial banks throughout the country.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [41, 516, 772, 771], \"page_id\": 28}], \"content\": \"Deposits to tax and loan accounts occur in the normal course of business under a uniform procedure applicable to all banks whereby customers of banks deposit with them tax payments and funds for the purchase of Government securities. In most cases the transaction involves merely the transfer of money from a customer's account to the tax and loan account in the same bank. On occasions, to the extent authorized by the\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 286, 1568, 429], \"page_id\": 28}], \"content\": \"Treasury, banks are permitted to deposit in these accounts proceeds from subscriptions to public debt securities entered for their own account as well as for the account of their customers.\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 439, 1571, 654], \"page_id\": 28}], \"content\": \"The tax and loan account system permits the Treasury to leave funds in banks and in the communities in which they arise until such time as the Treasury needs the funds for its operations. In this way the Treasury is able to neutralize the effect of its fluctuating operations on bank reserves and the economy.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [838, 659, 1569, 766], \"page_id\": 28}], \"content\": \"A detailed description of the Treasury's depositary system may be found in the Annual Report of the Secretary of the Treasury for 1955, pages 275-284.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [357, 916, 1281, 952], \"page_id\": 28}], \"content\": \"Table TUS-1. - Status of the Account of the Treasurer of the United States\", \"description\": null, \"id\": 9, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [708, 969, 945, 1003], \"page_id\": 28}], \"content\": \"(In millions of dollars)\", \"description\": null, \"id\": 10, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [39, 1001, 1586, 1783], \"page_id\": 28}], \"content\": \"<table><tr><th rowspan=\\\"2\\\">End of fiscal year or month</th><th colspan=\\\"4\\\">Treasury operating balance</th><th colspan=\\\"4\\\">Assets</th><th rowspan=\\\"2\\\">Liabilities 1/</th><th rowspan=\\\"2\\\">Balance in account of Treasurer of United States</th></tr><tr><th>Available funds in Federal Reserve banks</th><th>Tax and loan accounts in special depositaries</th><th>Gold balance in Treasury</th><th>Total operating balance</th><th>Silver balance, coinage metal, coin, and currency</th><th>Unclassified collections, etc.</th><th>In Federal Reserve banks in process of collection</th><th>In other depositaries</th><th>Total assets</th></tr><tr><td>1961</td><td>408</td><td>5,453</td><td>109</td><td>5,969</td><td>179</td><td>64</td><td>222</td><td>335</td><td>6,769</td><td>75</td><td>6,694</td></tr><tr><td>1962</td><td>612</td><td>8,815</td><td>121</td><td>9,548</td><td>147</td><td>70</td><td>303</td><td>441</td><td>10,509</td><td>79</td><td>10,430</td></tr><tr><td>1963</td><td>806</td><td>10,