iption\": null, \"id\": 9, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [34, 1769, 769, 1837], \"page_id\": 76}], \"content\": \"Because there is a normal lag in classifying redemptions, the distribution of redemption between sales price and accrued discount has been estimated. Beginning with the Treasury Bulletin of March 1961 the\", \"description\": null, \"id\": 10, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [856, 1437, 1525, 1514], \"page_id\": 76}], \"content\": \"method of distributing redemptions between sales price and accrued discount has been changed to reflect the distribution shown in final reports of classified redemptions. All periods shown have been revised on this basis.\", \"description\": null, \"id\": 11, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [819, 1512, 1512, 1573], \"page_id\": 76}], \"content\": \"Series F and G sales were discontinued April 30, 1952, and Series I and K sales were discontinued April 30, 1957. Sales figures after April 30, 1957, represent adjustments.\", \"description\": null, \"id\": 12, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [819, 1573, 1528, 1614], \"page_id\": 76}], \"content\": \"5/ Includes exchanges of Series 1941 F and G savings bonds for 3-1/4% marketable bonds of 1978-83.\", \"description\": null, \"id\": 13, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [817, 1611, 1536, 1652], \"page_id\": 76}], \"content\": \"6/ Includes exchanges of Series 1948 F and G bonds for 4-3/4% marketable notes of 1964.\", \"description\": null, \"id\": 14, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [817, 1650, 1498, 1691], \"page_id\": 76}], \"content\": \"7/ Includes exchanges of Series 1949 F and G bonds for 4% marketable bonds of 1969.\", \"description\": null, \"id\": 15, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [815, 1691, 1537, 1732], \"page_id\": 76}], \"content\": \"8/ Includes exchanges of Series 1950 F and G bonds for 3-7/8% marketable bonds of 1968.\", \"description\": null, \"id\": 16, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [815, 1730, 1518, 1771], \"page_id\": 76}], \"content\": \"9/ Includes exchanges of Series 1951 and 1952 F and G bonds for 3-7/8% marketable bonds of 1971 and 4% marketable bonds of 1980.\", \"description\": null, \"id\": 17, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [815, 1771, 1518, 1810], \"page_id\": 76}], \"content\": \"10/ Represents changes in the amounts of redemptions not yet classified between matured and unmatured issues.\", \"description\": null, \"id\": 18, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [815, 1808, 1045, 1829], \"page_id\": 76}], \"content\": \"Less than $500,000.\", \"description\": null, \"id\": 19, \"type\": \"footnote\"}, {\"bbox\": [{\"coord\": [27, 56, 221, 100], \"page_id\": 77}], \"content\": \"June 1970\", \"description\": null, \"id\": 0, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [1525, 68, 1557, 95], \"page_id\": 77}], \"content\": \"67\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [557, 112, 1038, 134], \"page_id\": 77}], \"content\": \"UNITED STATES SAVINGS NOTES\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [45, 255, 752, 353], \"page_id\": 77}], \"content\": \"Sales of United States savings notes began May 1, 1967. The notes are eligible for purchase by individuals with the simultaneous purchase of Series E savings bonds.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [839, 258, 1541, 387], \"page_id\": 77}], \"content\": \"The principal terms and conditions for purchase and redemption and information on investment yields of the savings notes appear in the Treasury Bulletins of March 1967 and June 1968.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [507, 482, 1086, 508], \"page_id\": 77}], \"content\": \"Table SN-1. - Sales and Redemptions by Periods\", \"description\": null, \"id\": 5, \"type\"