*sum_y) / (n*sum_x2 - sum_x^2)\n# a = (sum_y - b*sum_x) / n\n\nb = (n*sum_xy - sum_x*sum_y) / (n*sum_x2 - sum_x**2)\na = (sum_y - b*sum_x) / n\n\nprint(f\"\\nLinear regression:\")\nprint(f\"Slope (b): {b}\")\nprint(f\"Intercept (a): {a}\")\n\n# Round to nearest hundredths\nslope_rounded = round(b, 2)\nintercept_rounded = round(a, 2)\n\nprint(f\"\\nRounded values:\")\nprint(f\"Slope: {slope_rounded}\")\nprint(f\"Intercept: {intercept_rounded}\")\n\n# Output format\nprint(f\"\\nOutput: [{slope_rounded}, {intercept_rounded}]\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
